	summary := map[string]any{"from": from, "into": into, "strategy": strategy, "promoted": promoted, "proposals": proposalCount}
	if jsonOut {
		return writeJSON(cmd, summary)
	}
	fmt.Fprintf(cmd.OutOrStdout(), "promoted %d fact(s) from %s into %s (%s); %d conflict(s) queued for review\n", promoted, from, into, strategy, proposalCount)
	return nil
}"},{"rank":4,"score":93.995,"file_path":"internal/cli/facts_aliases.go","start_line":74,"end_line":77,"focus_line":74,"snippet_start_line":74,"snippet_end_line":77,"symbol_start_line":74,"symbol_end_line":76,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/facts_aliases.go:function:rejectProposal","symbol_name":"rejectProposal","qualified_name":"rejectProposal","signature":"func rejectProposal(facts []factRecord, p factProposal) []factRecord","signals":["body","signature","same-container-neighbor"],"snippet":"func rejectProposal(facts []factRecord, p factProposal) []factRecord {
